import{_ as o,a0 as d,w as p,s as r,ao as n,I as a,x as l,a1 as s,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"lnav: 用于 Linux 的高级日志文件浏览器 | LCTT x X-CMD","titleTemplate":false,"description":"lnav: 用于 Linux 的高级日志文件浏览器 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"lnav: 用于 Linux 的高级日志文件浏览器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"lnav: 用于 Linux 的高级日志文件浏览器 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221127.0 ⭐️ lnav Advanced Log File Viewer for Linux Desktops and Servers","title":"lnav: 用于 Linux 的高级日志文件浏览器","tag":"202301","desc":""},"relativePath":"202301/20221127.0 ⭐️ lnav Advanced Log File Viewer for Linux Desktops and Servers.md","filePath":"[post].md"}'),u={name:"202301/20221127.0 ⭐️ lnav Advanced Log File Viewer for Linux Desktops and Servers.md"};function g(h,i,b,k,v,f){const e=d("Link");return p(),r("div",null,[i[24]||(i[24]=n('<h1 id="lnav-用于-linux-的高级日志文件浏览器" tabindex="-1">lnav: 用于 Linux 的高级日志文件浏览器 <a class="header-anchor" href="#lnav-用于-linux-的高级日志文件浏览器" aria-label="Permalink to “lnav: 用于 Linux 的高级日志文件浏览器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/18/101616eio2v80m1v34ol2o.jpg" alt=""></p><blockquote><p>如果你想调试或排除任何问题，你需要一个像 lnav 这样的高级日志文件查看器。它在任何 Linux 系统的终端都能创造奇迹。</p></blockquote><h3 id="lnav-日志文件查看器" tabindex="-1">lnav: 日志文件查看器 <a class="header-anchor" href="#lnav-日志文件查看器" aria-label="Permalink to “lnav: 日志文件查看器”">​</a></h3><p><code>lnav</code> 可以即时解压缩所有的压缩日志文件，并将它们合并在一起进行漂亮的显示。显示是根据错误/警告的类型进行解析和格式化的，这有助于快速浏览成千上万的日志，特别是在服务器中。</p><p>在分析日志的时候，时间戳是非常重要的。所以 <code>lnav</code> 会根据时间戳合并多个日志，这对追踪系统问题很有帮助。</p><p>大多数重要的日志文件格式检测都是内置的，包括如下：</p><ul><li><ruby>通用网络访问日志<rt>Common Web Access Log</rt></ruby>格式</li><li>CUPS page_log</li><li>Syslog</li><li>Glog</li><li>VMware ESXi/vCenter 日志</li><li>dpkg.log</li><li>uwsgi</li><li>“通用”：任何以时间戳开头的信息</li><li>Strace</li><li>sudo</li><li>GZIP、BZIP</li></ul><p>这还不是全部，<code>lnav</code> 还能实现以下功能，使其成为 Linux 系统的重要应用：</p><ul><li>根据正则表达式过滤消息</li><li>错误日志的时间轴视图</li><li>漂亮的打印视图，这有助于重新格式化</li><li>使用 SQL 查询日志</li><li>在搜索时，日志会实时更新</li><li>通过正则表达式高亮显示语法（比如你想在整个日志中找出一个 IP 地址）</li><li>显示的日志中任何单词的 Tab 补全！!</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2016/11/lnav-Running-in-Ubutu.png" alt="lnav 在 ubuntu 中运行"></p>',11)),a("p",null,[i[1]||(i[1]=l("要查看上述功能的截图和了解更多信息，请访问 ",-1)),s(e,{href:"http://lnav.org/features/"},{default:t(()=>[...i[0]||(i[0]=[l("本页面",-1)])]),_:1}),i[2]||(i[2]=l(" 。",-1))]),i[25]||(i[25]=n('<h3 id="如何安装" tabindex="-1">如何安装 <a class="header-anchor" href="#如何安装" aria-label="Permalink to “如何安装”">​</a></h3><p>这个程序在 Ubuntu、Debian 的官方仓库中可以找到。使用以下命令安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lnav</span></span></code></pre></div><p>而对于 Fedora、RHEL 用户，使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install lnav</span></span></code></pre></div>',5)),a("p",null,[i[4]||(i[4]=l("另外，开发者还提供了一个离线的独立可执行文件，你不需要安装。你可以从 ",-1)),s(e,{href:"https://github.com/tstack/lnav/releases/"},{default:t(()=>[...i[3]||(i[3]=[l("GitHub 发布页",-1)])]),_:1}),i[5]||(i[5]=l(" 下载压缩包，然后按以下方式执行：",-1))]),i[26]||(i[26]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./lnav</span></span></code></pre></div><p><strong>注意</strong>：它也可用于 macOS，你可以在上述 GitHub 页面找到。</p><h3 id="lnav-如何使用-基础" tabindex="-1">lnav: 如何使用（基础） <a class="header-anchor" href="#lnav-如何使用-基础" aria-label="Permalink to “lnav: 如何使用（基础）”">​</a></h3><p>简单的命令语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lnav [options] [logfile1 logfile2 …]</span></span></code></pre></div><p>如果你直接运行 <code>lnav</code> 命令，它会显示你系统中的所有日志（<code>/var/log/messages</code> 和 <code>/var/log/syslog</code>)</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lnav</span></span></code></pre></div><p>要查看任何特定的日志文件，在命令行中输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lnav /var/log/syslog</span></span></code></pre></div><p>使用 <code>-t</code> 参数在你的日志输出中添加时间戳：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lnav -t /var/log/syslog</span></span></code></pre></div><p>以下是 <code>lnav</code> 的一些关键开关：</p><ul><li><code>-d file</code>：将调试信息写入给定的文件。</li><li><code>-a</code>：加载所有最新的日志文件类型。</li><li><code>-r</code>：也加载较早的轮转的日志文件。</li><li><code>-t</code>：在标准输入中读入的数据行上预加时间戳。</li><li><code>-w file</code>：将标准输入的内容写入该文件。</li><li><code>-c cmd</code>：在文件加载后执行命令。</li><li><code>-f path</code>：执行给定文件中的命令。</li><li><code>-n</code>：不使用 curses UI 运行（无头模式）。</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2016/11/lnav-running-in-Ubuntu-22.04.jpg" alt="lnav 在 Ubuntu 22.04 中运行"></p>',14)),a("p",null,[i[7]||(i[7]=l("要进一步阅读和探索，请访问 ",-1)),s(e,{href:"https://docs.lnav.org/en/latest/intro.html"},{default:t(()=>[...i[6]||(i[6]=[l("官方文档",-1)])]),_:1}),i[8]||(i[8]=l("。",-1))]),i[27]||(i[27]=a("hr",null,null,-1)),a("p",null,[i[10]||(i[10]=l("via: ",-1)),s(e,{href:"https://www.debugpoint.com/advanced-log-file-viewer-lnav-ubuntu-linux/"},{default:t(()=>[...i[9]||(i[9]=[l("https://www.debugpoint.com/advanced-log-file-viewer-lnav-ubuntu-linux/",-1)])]),_:1})]),a("p",null,[i[15]||(i[15]=l("作者：",-1)),s(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...i[11]||(i[11]=[l("Arindam",-1)])]),_:1}),i[16]||(i[16]=l(" 选题：",-1)),s(e,{href:"https://github.com/lkxed"},{default:t(()=>[...i[12]||(i[12]=[l("lkxed",-1)])]),_:1}),i[17]||(i[17]=l(" 译者：",-1)),s(e,{href:"https://github.com/geekpi"},{default:t(()=>[...i[13]||(i[13]=[l("geekpi",-1)])]),_:1}),i[18]||(i[18]=l(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[14]||(i[14]=[l("wxy",-1)])]),_:1})]),a("p",null,[i[21]||(i[21]=l("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[19]||(i[19]=[l("LCTT",-1)])]),_:1}),i[22]||(i[22]=l(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:t(()=>[...i[20]||(i[20]=[l("Linux中国",-1)])]),_:1}),i[23]||(i[23]=l(" 荣誉推出",-1))])])}const C=o(u,[["render",g]]);export{x as __pageData,C as default};
